alter table public.template_exercises add column if not exists target_reps_max integer;alter table public.template_exercises drop constraint if exists template_exercises_rep_range;alter table public.template_exercises add constraint template_exercises_rep_range check(target_reps_max is null or (target_reps_max between 1 and 1000 and target_reps_max>=target_reps));create or replace function public.save_template(payload jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$declare t public.workout_templates;item jsonb;begin if auth.uid() is null then raise exception 'Authentication required';end if;if payload->>'mutation_id' is null or payload->>'revision' is null or (payload->>'revision')::integer<0 then raise exception 'Mutation ID and revision required';end if;if jsonb_array_length(payload->'template_exercises') not between 1 and 50 then raise exception 'Choose between 1 and 50 exercises';end if;insert into public.workout_templates(id,user_id,name) values((payload->>'id')::uuid,auth.uid(),payload->>'name') on conflict(id) do nothing;select * into t from public.workout_templates where id=(payload->>'id')::uuid and archived_at is null for update;if t.id is null then raise exception 'Routine unavailable';end if;if t.last_mutation_id=(payload->>'mutation_id')::uuid then return jsonb_build_object('revision',t.revision);end if;if t.revision<>(payload->>'revision')::integer then raise exception 'VERSION_CONFLICT';end if;for item in select value from jsonb_array_elements(payload->'template_exercises') loop if not exists(select 1 from public.exercises e where e.id=(item->>'exercise_id')::uuid and e.archived_at is null) then raise exception 'Exercise unavailable';end if;if item->>'target_reps_max' is not null and (item->>'target_reps_max')::integer<(item->>'target_reps')::integer then raise exception 'The top of a rep range cannot be below the bottom';end if;end loop;delete from public.template_exercises where template_id=t.id;for item in select value from jsonb_array_elements(payload->'template_exercises') loop insert into public.template_exercises(id,template_id,exercise_id,position,target_sets,target_reps,target_reps_max,rest_seconds) values((item->>'id')::uuid,t.id,(item->>'exercise_id')::uuid,(item->>'position')::integer,(item->>'target_sets')::integer,(item->>'target_reps')::integer,(item->>'target_reps_max')::integer,(item->>'rest_seconds')::integer);end loop;update public.workout_templates set name=payload->>'name',revision=revision+1,last_mutation_id=(payload->>'mutation_id')::uuid where id=t.id returning * into t;return jsonb_build_object('revision',t.revision);end$$;